import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BGlkWkwp.js";const x=JSON.parse('{"title":"Textarea","description":"","frontmatter":{},"headers":[],"relativePath":"components/textarea.md","filePath":"components/textarea.md"}'),r={name:"components/textarea.md"};function n(i,e,s,c,h,l){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="textarea" tabindex="-1">Textarea <a class="header-anchor" href="#textarea" aria-label="Permalink to &quot;Textarea&quot;">​</a></h1><p>Textarea is the input of text of several lines.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a description, a comment or a note; one line of text is a <a href="./text-input">TextInput</a>. <code>rows</code> sets the least number of lines and <code>maxRows</code> the most it grows to; beyond them the text scrolls inside. The keys (send with Enter, cancel with Escape) are the application&#39;s, through <code>onkeydown</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>&#39;&#39;</code></td><td>The text (bindable)</td></tr><tr><td><code>placeholder</code></td><td></td><td>Shown while it is empty</td></tr><tr><td><code>rows</code></td><td><code>2</code></td><td>The least number of lines</td></tr><tr><td><code>maxRows</code></td><td></td><td>The most lines it grows to</td></tr><tr><td><code>ariaLabel</code></td><td></td><td>The accessible name without a Field</td></tr><tr><td><code>id</code></td><td></td><td>The id of the textarea</td></tr><tr><td><code>error</code></td><td><code>false</code></td><td>The line turns red</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be focused or changed</td></tr><tr><td><code>onchange</code>, <code>onblur</code></td><td></td><td>The committed value, and the loss of focus</td></tr><tr><td><code>onkeydown</code></td><td></td><td>The keys</td></tr><tr><td><code>el</code></td><td></td><td>The textarea element (bindable)</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is the control of a <a href="./text-input">TextInput</a>, whose height grows with the text. The lines take the running line height of body, and the padding above and below makes one line as high as a TextInput, with the text in the same place. Focus shows once, on the control&#39;s line; an error turns it red-ink.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/textarea/" title="Textarea" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/textarea/" target="_blank" rel="noopener">Textarea</a></figcaption></figure>',10)])])}const m=t(r,[["render",n]]);export{x as __pageData,m as default};
